@pytest.mark.parametrize('scope', ['module 4', ['module 1: Cơ sở'], 'Không phân giải được']) def test_w09_tools_create_real_quiz3_document3_with_server_identity_and_core_scope(chat, scope): from copy import deepcopy from doc2roadmap.domain.learning_graph import LearningGraph from wayfinder.fakes.lecture import ScriptedLectureModel w = chat payload = deepcopy(w.graph.payload) base = deepcopy(payload['nodes'][0]); payload['nodes'], payload['modules'] = [], [] for i in range(1, 5): nid, mid = f'n{i}', f'm{i}' payload['nodes'].append({**base, 'node_id': nid, 'module_id': mid}) distractors = [] for k, name in enumerate(['Phần tử', 'Quy tắc', 'Đặc điểm']): extra_id = f'{nid}_d{k}'; distractors.append(extra_id) payload['nodes'].append({**base, 'node_id': extra_id, 'name': name, 'display_name': name, 'module_id': mid}) payload['modules'].append({'module_id': mid, 'title': f'Cơ sở {i}', 'index': i - 1, 'node_ids': [nid, *distractors]}) payload['doc_id'] = 'doc-1' graph = LearningGraph(payload, list(w.graph.chunks.values())); graph.graph_version = 8 w.gateway.graph_loader = lambda *_: graph; w.gateway._graphs.clear() doc_model = ScriptedLectureModel([['# Tài liệu ôn tập\n\nMột tập hợp gồm các phần tử. [S1]']]) w.gateway.runtime.model_for = lambda purpose: w.model if purpose == 'assistant' else doc_model if purpose == 'document' else None w.model.tool_turns = [ [ToolCall('make_quiz', {'scope': scope, 'n': 1, 'owner': 'forged', 'doc_id': 'other', 'graph_version': 999}, 'quiz'), Done({})], [ToolCall('make_document', {'request': 'Tóm tắt giúp tôi', 'scope': scope, 'owner': 'forged'}, 'doc'), Done({})], [Delta('Đã tạo xong. [Link giả](quiz:not-real)'), Done({})], ] sid = create(w, scope={'kind': 'module', 'module_id': 'm1'})['session_id'] rows = events(ask(w, sid)); final = rows[-1]['answer'] assert {row['artifact']['kind'] for row in rows if row['event'] == 'artifact'} == {'quiz', 'document'}, [ (call['name'], call['result_summary']) for turn in w.phase_b.list_records('turn') for call in turn['answer'].get('tool_calls', [])] assert len(final['artifacts']) == 2 timeline = [(row['event'], row.get('name') if row['event'] == 'tool_call' else row.get('artifact', {}).get('kind'), row.get('state')) for row in rows] assert timeline.index(('tool_call', 'make_quiz', 'running')) < timeline.index(('artifact', 'quiz', None)) > assert timeline.index(('artifact', 'quiz', None)) < timeline.index(('tool_call', 'make_document', 'running')) E AssertionError: assert 9 < 4 E + where 9 = <built-in method index of list object at 0x00000188C75BA600>(('artifact', 'quiz', None)) E + where <built-in method index of list object at 0x00000188C75BA600> = [('progress', None, None), ('tool_call', 'make_quiz', 'running'), ('tool_call', 'make_quiz', 'done'), ('progress', None, None), ('tool_call', 'make_document', 'running'), ('tool_call', 'make_document', 'done'), ...].index E + and 4 = <built-in method index of list object at 0x00000188C75BA600>(('tool_call', 'make_document', 'running')) E + where <built-in method index of list object at 0x00000188C75BA600> = [('progress', None, None), ('tool_call', 'make_quiz', 'running'), ('tool_call', 'make_quiz', 'done'), ('progress', None, None), ('tool_call', 'make_document', 'running'), ('tool_call', 'make_document', 'done'), ...].index
